const KEYS=["animals","equipment","fish","gangs","plants","horses","weapons","cards"],STORE="rdr2-compendium-v1",NOTES_STORE="rdr2-compendium-notes-v1",COATS_STORE="rdr2-compendium-horse-coats-v1",THEME="rdr2-full-checklist-theme",LANGUAGE="rdr2-full-checklist-lang";
let active=localStorage.getItem("rdr2-compendium-category")||"animals",filter="all",query="",page=1;
const PAGE_SIZE=30;
let lang=localStorage.getItem(LANGUAGE)==="en"?"en":"zh";
let state={};try{state=JSON.parse(localStorage.getItem(STORE)||"{}")||{}}catch(e){}
let notes={};try{notes=JSON.parse(localStorage.getItem(NOTES_STORE)||"{}")||{}}catch(e){}
