function coatId(breedId,i){return "horsecoat-"+breedId.slice(7)+"-"+(i+1)}
function englishText(text){return String(text==null?"":text).replace(/\s*·\s*/g," / ")}
function L(zh,en){return lang==="en"?englishText(en):zh}
function core(item){return !item.optional}
function counts(cat){const a=DATA[cat].filter(core);return {done:a.filter(x=>state[x.id]).length,total:a.length}}
function allCounts(){let done=0,total=0;KEYS.forEach(k=>{const c=counts(k);done+=c.done;total+=c.total});return {done,total}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
const DESC_EN={animals:"178 animals in in-game Compendium order",equipment:"77 standard-edition entries plus 2 edition-exclusive entries",fish:"15 common fish and 15 legendary fish",gangs:"6 enemy gangs",plants:"43 plants in in-game Compendium order",horses:"19 horse breeds",weapons:"63 weapons in the updated Story Mode Compendium",cards:"12 sets of 12 cards"};
function renderTabs(){document.getElementById("tabs").innerHTML=KEYS.map(k=>{const c=counts(k);return '<button class="tab '+(k===active?'active':'')+'" data-cat="'+k+'"><b>'+esc(L(META[k].zh,META[k].en))+'</b><span>'+c.done+' / '+c.total+'</span></button>'}).join("")}
function badgeHTML(x){let a=[];if(x.legendary)a.push('<span class="badge">'+L("传说","Legendary")+'</span>');if(x.optional)a.push('<span class="badge optional">'+L("特别版/终极版限定","Special/Ultimate Edition")+'</span>');return a.length?'<div class="badges">'+a.join("")+'</div>':""}
function horseCoatsHTML(x){const coats=HORSE_COATS[x.id];if(!coats)return "";const done=coats.filter((_,i)=>coatState[coatId(x.id,i)]).length;return '<details class="horse-coats"><summary><span>'+L("花色","Coats")+' <b data-coat-count="'+x.id+'">'+done+' / '+coats.length+'</b></span></summary><div class="coat-list">'+coats.map((c,i)=>{const id=coatId(x.id,i),checked=!!coatState[id];return '<label class="coat-item"><input class="coat-check" type="checkbox" data-breed-id="'+x.id+'" data-coat-id="'+id+'" '+(checked?'checked':'')+'><span class="coat-name">'+esc(L(c[0],c[1]))+(c[2]?'<small>'+esc(L(c[2][0],c[2][1]))+'</small>':'')+'</span></label>'}).join("")+'</div></details>'}
function entryHTML(x,i){const title=lang==="en"?englishText(x.name):x.zh;return '<article class="entry '+(state[x.id]?'done':'')+'" data-id="'+x.id+'" data-set="'+x.set+'" data-search="'+esc((x.zh+" "+x.name+" "+(notes[x.id]||"")).toLowerCase())+'"><label class="entry-main"><input class="entry-check" type="checkbox" '+(state[x.id]?'checked':'')+'><div><div class="entry-name">'+esc(title)+'</div>'+badgeHTML(x)+'</div><span class="num">'+String(i+1).padStart(3,"0")+'</span></label>'+horseCoatsHTML(x)+'<input class="entry-memo" type="text" data-memo-id="'+x.id+'" value="'+esc(notes[x.id]||"")+'" placeholder="'+L("我的备注…","My notes…")+'" aria-label="'+L("备注","Notes")+'：'+esc(title)+'"></article>'}
function cardSetsHTML(items){return '<div class="card-sets">'+CARD_SETS_EN.map((en,set)=>{const setItems=items.filter(x=>x.set===set),zh=CARD_SETS_ZH[set],done=setItems.filter(x=>state[x.id]).length,title=lang==="zh"?esc(zh):esc(en);return '<details class="card-set" data-card-set="'+set+'"><summary><span class="card-set-title">'+title+'</span><span class="card-set-count" data-set-count="'+set+'">'+done+' / '+setItems.length+'</span></summary><div class="card-set-grid">'+setItems.map(x=>entryHTML(x,items.indexOf(x))).join("")+'</div></details>'}).join("")+'</div>'}
function render(){renderTabs();const items=DATA[active],m=META[active];let heading=lang==="zh"?m.zh:m.en;let body=active==="cards"?cardSetsHTML(items):'<div class="grid" id="grid">'+items.map((x,i)=>entryHTML(x,i)).join("")+'</div>';let out='<div class="catintro"><h2>'+heading+'</h2></div>'+body+'<nav class="pagination" id="pagination" aria-label="'+L("分页","Pagination")+'"></nav><div class="empty" id="empty" hidden>'+L("没有符合当前条件的条目","No entries match the current filters")+'</div>';document.getElementById("content").innerHTML=out;applyFilter();progress();syncChrome()}
function entryMatches(el){const done=!!state[el.dataset.id];return el.dataset.search.includes(query)&&(filter==="all"||(filter==="done"&&done)||(filter==="todo"&&!done))}
function renderPagination(totalPages){const nav=document.getElementById("pagination");if(!nav)return;if(totalPages<=1){nav.innerHTML="";return}let html='<button class="page-btn" data-page="prev" '+(page===1?'disabled':'')+'>'+L("上一页","Previous")+'</button>';for(let i=1;i<=totalPages;i++)html+='<button class="page-btn '+(i===page?'active':'')+'" data-page="'+i+'" '+(i===page?'aria-current="page"':'')+'>'+i+'</button>';html+='<button class="page-btn" data-page="next" '+(page===totalPages?'disabled':'')+'>'+L("下一页","Next")+'</button>';nav.innerHTML=html}
function applyFilter(){const entries=Array.from(document.querySelectorAll(".entry")),matched=entries.filter(entryMatches);let shown=matched.length;if(active==="cards"){entries.forEach(el=>el.classList.toggle("hidden",!entryMatches(el)));document.querySelectorAll(".card-set").forEach(set=>{const visible=!!set.querySelector(".entry:not(.hidden)");set.classList.toggle("hidden",!visible);if(query&&visible)set.open=true});renderPagination(1)}else{const paginated=DATA[active].length>PAGE_SIZE,totalPages=paginated?Math.max(1,Math.ceil(matched.length/PAGE_SIZE)):1;page=Math.min(Math.max(1,page),totalPages);const start=(page-1)*PAGE_SIZE,end=start+PAGE_SIZE;entries.forEach(el=>el.classList.add("hidden"));matched.forEach((el,i)=>el.classList.toggle("hidden",paginated&&(i<start||i>=end)));renderPagination(totalPages)}const empty=document.getElementById("empty");if(empty)empty.hidden=shown>0}
function updateCardSetCounts(){document.querySelectorAll("[data-set-count]").forEach(el=>{const set=Number(el.dataset.setCount),items=DATA.cards.filter(x=>x.set===set);el.textContent=items.filter(x=>state[x.id]).length+" / "+items.length})}
function progress(){const c=allCounts();document.documentElement.classList.toggle("is-legend",c.total>0&&c.done===c.total);document.getElementById("overall").textContent=c.done+" / "+c.total;document.getElementById("overall-bar").style.width=(c.total?c.done/c.total*100:0)+"%";renderTabs();updateCardSetCounts()}
document.addEventListener("click",e=>{const tab=e.target.closest("[data-cat]");if(tab){active=tab.dataset.cat;page=1;localStorage.setItem("rdr2-compendium-category",active);query="";document.getElementById("search").value="";render();return}const f=e.target.closest("[data-filter]");if(f){filter=f.dataset.filter;page=1;document.querySelectorAll("[data-filter]").forEach(b=>b.classList.toggle("active",b===f));applyFilter();return}const pager=e.target.closest("[data-page]");if(pager&&!pager.disabled){const pages=document.querySelectorAll('.page-btn[data-page]:not([data-page="prev"]):not([data-page="next"])').length;page=pager.dataset.page==="prev"?page-1:pager.dataset.page==="next"?page+1:Number(pager.dataset.page);page=Math.min(Math.max(1,page),pages);applyFilter();document.querySelector(".catintro").scrollIntoView({behavior:"smooth",block:"start"});return}})
document.addEventListener("change",e=>{if(e.target.matches(".entry-check")){const entry=e.target.closest(".entry"),id=entry.dataset.id;state[id]=e.target.checked;if(!state[id])delete state[id];localStorage.setItem(STORE,JSON.stringify(state));entry.classList.toggle("done",e.target.checked);progress();applyFilter();return}if(e.target.matches(".coat-check")){const breedId=e.target.dataset.breedId,coatIdValue=e.target.dataset.coatId;if(e.target.checked)coatState[coatIdValue]=true;else delete coatState[coatIdValue];localStorage.setItem(COATS_STORE,JSON.stringify(coatState));const coats=HORSE_COATS[breedId],entry=e.target.closest(".entry"),count=entry.querySelector("[data-coat-count]");if(count)count.textContent=coats.filter((_,i)=>coatState[coatId(breedId,i)]).length+" / "+coats.length}})
document.addEventListener("input",e=>{if(!e.target.matches(".entry-memo"))return;const id=e.target.dataset.memoId,value=e.target.value;if(value)notes[id]=value;else delete notes[id];localStorage.setItem(NOTES_STORE,JSON.stringify(notes));const entry=e.target.closest(".entry"),item=DATA[active].find(x=>x.id===id);if(entry&&item)entry.dataset.search=(item.zh+" "+item.name+" "+value).toLowerCase()})
document.getElementById("search").addEventListener("input",e=>{query=e.target.value.trim().toLowerCase();page=1;applyFilter()})
function applyTheme(t){if(t==="light"||t==="dark")document.documentElement.dataset.theme=t;else document.documentElement.removeAttribute("data-theme");theme=t;syncChrome()}
function syncChrome(){document.documentElement.lang=lang==="en"?"en":"zh-CN";document.documentElement.dataset.lang=lang;document.title=L("图鉴","RDR2 Compendium");document.getElementById("page-title").textContent=L("图鉴","Compendium");document.querySelector(".eyebrow").textContent=lang==="zh"?"":"RED DEAD REDEMPTION 2";document.getElementById("back-link").textContent=L("返回","Back");document.getElementById("search").placeholder=L("搜索当前分类…","Search this category…");document.getElementById("search").setAttribute("aria-label",L("搜索当前分类","Search this category"));document.getElementById("summary").setAttribute("aria-label",L("总完成度","Total completion"));document.getElementById("tabs").setAttribute("aria-label",L("图鉴分类","Compendium categories"));document.getElementById("filters").setAttribute("aria-label",L("完成状态筛选","Completion status filter"));document.getElementById("source-note").textContent=L("数据来源于对多个 RDR2 攻略站点的交叉整理核实,部分坐标/挑战措辞未能逐条百分百核实(已在对应条目注明),建议以游戏内实际显示为准。","Data cross-checked and compiled from multiple RDR2 guide sites; a few coordinates/challenge wordings could not be verified line-by-line (flagged on the relevant entries) — treat the in-game display as authoritative.");document.getElementById("copyright-note").textContent="© "+new Date().getFullYear()+" Jam8ee";const labels=lang==="en"?["All","Incomplete","Completed"]:["全部","未完成","已完成"];document.querySelectorAll("[data-filter]").forEach((b,i)=>b.textContent=labels[i])}
let theme=localStorage.getItem(THEME)||"auto";applyTheme(theme);
function followMainSettings(){const nextTheme=localStorage.getItem(THEME)||"auto",nextLang=localStorage.getItem(LANGUAGE)==="en"?"en":"zh";lang=nextLang;try{state=JSON.parse(localStorage.getItem(STORE)||"{}")||{}}catch(e){state={}}try{notes=JSON.parse(localStorage.getItem(NOTES_STORE)||"{}")||{}}catch(e){notes={}}try{coatState=JSON.parse(localStorage.getItem(COATS_STORE)||"{}")||{}}catch(e){coatState={}}applyTheme(nextTheme);render()}
window.addEventListener("focus",followMainSettings);window.addEventListener("storage",followMainSettings);
render();
